//! Tempo output settings: what the settings panel edits and persists.
//!
//! These are plain, unvalidated values — strings and numbers as the user
//! typed them. [`TempoOutputConfig::validate`] (see [`crate::validation`])
//! turns them into something the run loop can use without re-checking.
//!
//! The model is a routing table: [`OscTarget`]s say *where* OSC goes,
//! [`OscMessageConfig`]s say *what* is sent (from which deck, on which
//! trigger, in which format) and which targets receive it. Ids are opaque
//! strings generated by the UI.

use decktector_core::model::DeckId;
use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Highest deck number a [`TempoSource::Deck`] may name (the decks are 1-6).
pub const MAX_DECK_ID: DeckId = 6;

/// Most decimals `{bpm}` may be formatted with in a template.
pub const MAX_BPM_DECIMALS: u8 = 2;

/// Where tempo OSC goes.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "OscTarget.ts")]
pub struct OscTarget {
    /// Opaque id messages refer to in [`OscMessageConfig::target_ids`].
    pub id: String,
    /// Label shown in the UI; never used for routing.
    pub name: String,
    /// An IPv4 literal; a broadcast address (e.g. `192.168.1.255`) is fine.
    pub host: String,
    pub port: u16,
    /// A disabled target receives nothing and raises no issue.
    pub enabled: bool,
}

/// Which deck a message speaks for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(
    tag = "type",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
#[ts(export, export_to = "TempoSource.ts")]
pub enum TempoSource {
    /// Whichever deck is the tempo master right now; the deck may change.
    Master,
    /// One given deck (1-6).
    Deck { deck_id: DeckId },
}

/// What makes a [`MessageKind::Custom`] message go out.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "Trigger.ts")]
pub enum Trigger {
    /// The source's BPM.
    Bpm,
    /// The source's beat becoming 1.
    BarStart,
    /// Any change of the source's beat.
    EachBeat,
}

/// How often an unchanged BPM is sent again.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "BpmRefresh.ts")]
pub enum BpmRefresh {
    /// Only when the sent packet differs from the previous one.
    OnChange,
    /// On change, and once a second, so a receiver started mid-set (or one
    /// that dropped a packet) catches up.
    OnChangeAndEverySecond,
}

/// The argument of a [`MessageKind::Custom`] message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(
    tag = "type",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
#[ts(export, export_to = "CustomValue.ts")]
pub enum CustomValue {
    /// A float: the BPM, or the beat number for beat triggers.
    FloatRaw,
    /// A float scaled so `min` maps to 0 and `max` to 1, clamped to 0..=1.
    /// `min` must be below `max`.
    FloatNormalized { min: f64, max: f64 },
    /// An integer: the BPM rounded, or the beat number.
    Int,
    /// A string where `{bpm}`, `{beat}` and `{deck}` are substituted.
    Template { template: String },
    /// No argument at all: the message itself is the signal.
    NoArgument,
}

/// What a message carries and when it goes out.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(
    tag = "type",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
#[ts(export, export_to = "MessageKind.ts")]
pub enum MessageKind {
    /// The raw BPM as a float.
    Bpm { refresh: BpmRefresh },
    /// Integer `1` when the source's beat becomes 1.
    BarStart,
    /// The beat (1-4) as an integer on every beat change.
    EachBeat,
    /// Free choice of trigger and argument.
    Custom {
        trigger: Trigger,
        value: CustomValue,
        /// Decimals `{bpm}` is formatted with in a template, `0..=2`.
        bpm_decimals: u8,
        /// Only used when `trigger` is [`Trigger::Bpm`].
        refresh: BpmRefresh,
    },
}

/// One OSC message the user wants sent, and to whom.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "OscMessageConfig.ts")]
pub struct OscMessageConfig {
    /// Opaque id issues are reported against.
    pub id: String,
    /// A disabled message is not sent and raises no issue.
    pub enabled: bool,
    pub source: TempoSource,
    pub kind: MessageKind,
    /// The OSC address, e.g. `/decktective/master/bpm`.
    pub address: String,
    /// The targets (by [`OscTarget::id`]) that receive this message.
    pub target_ids: Vec<String>,
}

/// Settings of the tempo output.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "TempoOutputConfig.ts")]
pub struct TempoOutputConfig {
    pub enabled: bool,
    pub targets: Vec<OscTarget>,
    pub messages: Vec<OscMessageConfig>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_is_disabled_with_no_targets_and_no_messages() {
        let config = TempoOutputConfig::default();
        assert!(!config.enabled);
        assert!(config.targets.is_empty());
        assert!(config.messages.is_empty());
    }

    #[test]
    fn source_is_tagged_with_type_and_camel_case() {
        assert_eq!(
            serde_json::to_string(&TempoSource::Master).unwrap(),
            r#"{"type":"master"}"#
        );
        assert_eq!(
            serde_json::to_string(&TempoSource::Deck { deck_id: 3 }).unwrap(),
            r#"{"type":"deck","deckId":3}"#
        );
    }

    #[test]
    fn kinds_round_trip_through_json() {
        let kinds = [
            MessageKind::Bpm {
                refresh: BpmRefresh::OnChangeAndEverySecond,
            },
            MessageKind::BarStart,
            MessageKind::EachBeat,
            MessageKind::Custom {
                trigger: Trigger::EachBeat,
                value: CustomValue::FloatNormalized { min: 1.0, max: 4.0 },
                bpm_decimals: 1,
                refresh: BpmRefresh::OnChange,
            },
        ];
        for kind in kinds {
            let json = serde_json::to_string(&kind).unwrap();
            assert_eq!(serde_json::from_str::<MessageKind>(&json).unwrap(), kind);
        }
    }

    #[test]
    fn custom_kind_uses_camel_case_field_names() {
        let json = serde_json::to_value(MessageKind::Custom {
            trigger: Trigger::BarStart,
            value: CustomValue::Template {
                template: "{bpm}".to_string(),
            },
            bpm_decimals: 2,
            refresh: BpmRefresh::OnChange,
        })
        .unwrap();
        assert_eq!(json["type"], "custom");
        assert_eq!(json["trigger"], "barStart");
        assert_eq!(json["bpmDecimals"], 2);
        assert_eq!(json["refresh"], "onChange");
        assert_eq!(json["value"]["type"], "template");
        assert_eq!(json["value"]["template"], "{bpm}");
    }

    #[test]
    fn normalized_value_serializes_its_bounds() {
        let json = serde_json::to_value(CustomValue::FloatNormalized {
            min: 60.0,
            max: 180.0,
        })
        .unwrap();
        assert_eq!(json["type"], "floatNormalized");
        assert_eq!(json["min"], 60.0);
        assert_eq!(json["max"], 180.0);
    }
}
